CREATE TABLE public.hr_employees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL, auth_user_id uuid UNIQUE, name text NOT NULL, email text NOT NULL DEFAULT '', cpf text NOT NULL DEFAULT '', birth_date date, phone text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', job_title text NOT NULL, salary numeric NOT NULL DEFAULT 0 CHECK(salary >= 0), hired_on date NOT NULL, active boolean NOT NULL DEFAULT true, shift_start text NOT NULL DEFAULT '08:00', sunday_interval integer NOT NULL DEFAULT 4 CHECK(sunday_interval IN (2,4)), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hr_employees TO authenticated; GRANT ALL ON public.hr_employees TO service_role;
ALTER TABLE public.hr_employees ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.hr_is_admin(_account uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND account_id = _account AND role = 'admin') $$;
REVOKE ALL ON FUNCTION public.hr_is_admin(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.hr_is_admin(uuid) TO authenticated;
CREATE POLICY hr_employee_read ON public.hr_employees FOR SELECT TO authenticated USING(public.hr_is_admin(account_id) OR auth_user_id = auth.uid());
CREATE TABLE public.hr_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL, employee_id uuid REFERENCES public.hr_employees(id), kind text NOT NULL CHECK(kind IN ('schedule','vacation','absence','payroll','acknowledgment','settings')), period text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'draft', payload jsonb NOT NULL DEFAULT '{}', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hr_entries TO authenticated; GRANT ALL ON public.hr_entries TO service_role;
ALTER TABLE public.hr_entries ENABLE ROW LEVEL SECURITY;
CREATE POLICY hr_entry_read ON public.hr_entries FOR SELECT TO authenticated USING(public.hr_is_admin(account_id) OR (employee_id IN (SELECT id FROM public.hr_employees WHERE auth_user_id = auth.uid()) AND (kind <> 'payroll' OR status = 'published')));
CREATE UNIQUE INDEX hr_payroll_period ON public.hr_entries(employee_id,period) WHERE kind = 'payroll';
CREATE UNIQUE INDEX hr_schedule_period ON public.hr_entries(account_id,period) WHERE kind = 'schedule';
CREATE UNIQUE INDEX hr_ack_period ON public.hr_entries(employee_id,period) WHERE kind = 'acknowledgment';
CREATE TABLE public.hr_punches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL, employee_id uuid NOT NULL REFERENCES public.hr_employees(id), kind text NOT NULL CHECK(kind IN ('entrada','intervalo_saida','intervalo_volta','saida')), recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(), latitude numeric NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude numeric NOT NULL CHECK(longitude BETWEEN -180 AND 180), accuracy numeric NOT NULL CHECK(accuracy >= 0), actor_id uuid NOT NULL, sequence bigint GENERATED ALWAYS AS IDENTITY, receipt_hash text NOT NULL DEFAULT '');
GRANT SELECT ON public.hr_punches TO authenticated; GRANT ALL ON public.hr_punches TO service_role; GRANT USAGE, SELECT ON SEQUENCE public.hr_punches_sequence_seq TO service_role;
ALTER TABLE public.hr_punches ENABLE ROW LEVEL SECURITY;
CREATE POLICY hr_punch_read ON public.hr_punches FOR SELECT TO authenticated USING(public.hr_is_admin(account_id) OR employee_id IN (SELECT id FROM public.hr_employees WHERE auth_user_id = auth.uid()));
CREATE FUNCTION public.hr_record_punch(_employee uuid, _kind text, _latitude numeric, _longitude numeric, _accuracy numeric) RETURNS public.hr_punches LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE e public.hr_employees; p public.hr_punches; lastp public.hr_punches; expected text; BEGIN SELECT * INTO e FROM public.hr_employees WHERE id = _employee AND active FOR UPDATE; IF e.id IS NULL OR auth.uid() IS NULL OR NOT(e.auth_user_id = auth.uid() OR public.hr_is_admin(e.account_id)) THEN RAISE EXCEPTION 'Acesso negado'; END IF; SELECT * INTO lastp FROM public.hr_punches WHERE employee_id = e.id ORDER BY sequence DESC LIMIT 1; expected := CASE WHEN lastp.id IS NULL OR lastp.kind = 'saida' THEN 'entrada' WHEN lastp.kind = 'entrada' THEN 'intervalo_saida' WHEN lastp.kind = 'intervalo_saida' THEN 'intervalo_volta' ELSE 'saida' END; IF _kind <> expected THEN RAISE EXCEPTION 'Sequência inválida de ponto'; END IF; IF _kind = 'entrada' AND lastp.id IS NOT NULL AND clock_timestamp() - lastp.recorded_at < interval '11 hours' THEN RAISE EXCEPTION 'Interjornada inferior a 11 horas'; END IF; INSERT INTO public.hr_punches(account_id,employee_id,kind,latitude,longitude,accuracy,actor_id) VALUES(e.account_id,e.id,_kind,_latitude,_longitude,_accuracy,auth.uid()) RETURNING * INTO p; UPDATE public.hr_punches SET receipt_hash = encode(sha256(convert_to(p.id::text || p.recorded_at::text || coalesce(lastp.receipt_hash,''),'UTF8')),'hex') WHERE id = p.id RETURNING * INTO p; RETURN p; END $$;
REVOKE ALL ON FUNCTION public.hr_record_punch(uuid,text,numeric,numeric,numeric) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.hr_record_punch(uuid,text,numeric,numeric,numeric) TO authenticated;
CREATE POLICY hr_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id = 'hr-documents' AND EXISTS(SELECT 1 FROM public.hr_employees e WHERE e.id::text = (storage.foldername(name))[2] AND e.account_id::text = (storage.foldername(name))[1] AND (public.hr_is_admin(e.account_id) OR e.auth_user_id = auth.uid())));
CREATE POLICY hr_files_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id = 'hr-documents' AND EXISTS(SELECT 1 FROM public.hr_employees e WHERE e.id::text = (storage.foldername(name))[2] AND e.account_id::text = (storage.foldername(name))[1] AND e.active AND (public.hr_is_admin(e.account_id) OR e.auth_user_id = auth.uid())));
CREATE POLICY hr_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id = 'hr-documents' AND EXISTS(SELECT 1 FROM public.hr_employees e WHERE e.id::text = (storage.foldername(name))[2] AND e.account_id::text = (storage.foldername(name))[1] AND public.hr_is_admin(e.account_id)));
ALTER PUBLICATION supabase_realtime ADD TABLE public.hr_employees, public.hr_entries, public.hr_punches;
COMMENT ON TABLE public.hr_punches IS 'Internal time records, not a certified REP-P; immutable through authenticated Data API.';